import Base

type W_Palette is Data:
  W_Palette{air: U32, stone: U32, dirt: U32, planks: U32}

type W_Cell is Data:
  W_Cell{x: U32, y: U32, z: U32, boundary: U32}

type W_RawBlock is Data:
  W_RawBlock{cell: W_Cell, state: U32, material: U32}

def W_choose(-T: Data, yes: T, no: T, value: Bool) -> T:
  match value:
    case True{}: yes
    case False{}: no

type R_Block is Data:
  R_Block{x: F32,y: F32,z: F32,state: U32,material: U32}

type R_Camera is Data:
  R_Camera{x: F32,y: F32,z: F32,yaw: F32,pitch: F32}

type R_Snapshot is Data:
  R_Snapshot{tick: Nat,revision: Nat,blocks: List<&2,R_Block>,camera: R_Camera}

type M_Vec3 is Data:
  M_Vec3{x:F32,y:F32,z:F32}

type M_UV is Data:
  M_UV{u:F32,v:F32}

type M_Vertex is Data:
  M_Vertex{position:M_Vec3,uv:M_UV}

type M_Mode is Data:
  M_Opaque{}
  M_Cutout{threshold:U32}
  M_Translucent{}

type M_Address is Data:
  M_Clamp{}
  M_Repeat{}

type M_Cull is Data:
  M_NoCull{}
  M_Back{}

type M_Material is Data:
  M_Material{texture:U32,tint:U32,light:U32,shade:F32,mode:M_Mode,address:M_Address}

type M_Quad is Data:
  M_Quad{a:M_Vertex,b:M_Vertex,c:M_Vertex,d:M_Vertex,material:M_Material,cull:M_Cull,order:U32}

type B_Direction is Data:
  B_Down{}
  B_Up{}
  B_North{}
  B_South{}
  B_West{}
  B_East{}

type K_Layer is Data:
  K_Solid{}
  K_Cutout{}
  K_Translucent{}

type K_Baked is Data:
  K_Baked{a:M_Vertex,b:M_Vertex,c:M_Vertex,d:M_Vertex,direction:B_Direction,
    cullface:Maybe<&2,B_Direction>,sprite:String,texture:U32,tint_index:U32,
    light_emission:U32,shade_override:Maybe<&2,B_Direction>,layer:K_Layer,
    force_translucent:Bool,animated:Bool,default_shade:F32,nether_shade:F32}

type WM_Tint is Data:
  WM_Tint{index:U32,color:U32}

type WM_Appearance is Data:
  WM_Appearance{tints:List<&2,WM_Tint>,light:U32,address:M_Address,cull:M_Cull,
    nether:Bool,cutout_threshold:U32}

type WM_Binding is Data:
  WM_Binding{state:U32,baked:List<&2,K_Baked>,appearance:WM_Appearance}

def WM_lookup(bindings:List<&2,WM_Binding>,+state:U32) -> Maybe<&2,WM_Binding>:
  match bindings:
    case Nil{}: None{}
    case +head <> tail:
      WM_Binding{current,baked,appearance} = head
      W_choose(Maybe<&2,WM_Binding>,Some{head},WM_lookup(tail,state),U32.is_eq(current,state))

type Class is Data:
  Air{}
  FullCube{}

type Visibility is Data:
  Visibility{cell:W_Cell,state:U32,visible:U32}

type Error is Data:
  Error{code:String,cell:W_Cell,state:U32,detail:String}

def empty_cell() -> W_Cell:
  W_Cell{0,0,0,0}

def direction_bit(direction:B_Direction) -> U32:
  match direction:
    case B_Down{}: 1
    case B_Up{}: 2
    case B_North{}: 4
    case B_South{}: 8
    case B_West{}: 16
    case B_East{}: 32

# U32 arithmetic preserves BlockPos.relative's signed Java int wraparound.
# boundary is region metadata, not part of a raw cell's identity.

def neighbor(cell:W_Cell,direction:B_Direction) -> W_Cell:
  W_Cell{x,y,z,boundary} = cell
  match direction:
    case B_Down{}: W_Cell{x,U32.sub(y,1),z,0}
    case B_Up{}: W_Cell{x,U32.inc(y),z,0}
    case B_North{}: W_Cell{x,y,U32.sub(z,1),0}
    case B_South{}: W_Cell{x,y,U32.inc(z),0}
    case B_West{}: W_Cell{U32.sub(x,1),y,z,0}
    case B_East{}: W_Cell{U32.inc(x),y,z,0}

def same_cell(a:W_Cell,b:W_Cell) -> Bool:
  match a b:
    case W_Cell{x,y,z,boundary} W_Cell{bx,by,bz,bb}:
      U32.is_eq(x,bx) && U32.is_eq(y,by) && U32.is_eq(z,bz)

def palette_valid(palette:W_Palette) -> Bool:
  W_Palette{+air,+stone,+dirt,+planks} = palette
  U32.is_ne(air,stone) && U32.is_ne(air,dirt) && U32.is_ne(air,planks) &&
    U32.is_ne(stone,dirt) && U32.is_ne(stone,planks) && U32.is_ne(dirt,planks)

def classify(+state:U32,palette:W_Palette,cell:W_Cell) -> Result<&2,&2,Error,Class>:
  W_Palette{air,stone,dirt,planks} = palette
  W_choose(Result<&2,&2,Error,Class>,Done{Air{}},
    W_choose(Result<&2,&2,Error,Class>,Done{FullCube{}},
      Fail{Error{"UnsupportedState",cell,state,"unmeasured-occlusion-state"}},
      U32.is_eq(state,stone) || U32.is_eq(state,dirt) || U32.is_eq(state,planks)),U32.is_eq(state,air))

# Adjacent Shapes.block() is the first Java short circuit; all measured
# solid states use it. The measured air shape is Shapes.empty().

def visible_classes(current:Class,adjacent:Class) -> Bool:
  match adjacent:
    case FullCube{}: False{}
    case Air{}: True{}

law adjacent_full_cube_hides:
  for current:Class
  {visible_classes(current,FullCube{}) == False{} : Bool}

def adjacent_full_cube_hides(current):
  {==}

def should_render_face(current:U32,adjacent:U32,+palette:W_Palette,+cell:W_Cell) -> Result<&2,&2,Error,Bool>:
  do Result<&2,&2,Error,Bool>:
    own : Class <- classify(current,palette,cell)
    other : Class <- classify(adjacent,palette,cell)
    Done{visible_classes(own,other)}

def group_visible(group:Maybe<&2,B_Direction>,+visible:U32) -> Bool:
  match group:
    case None{}: True{}
    case Some{direction}: U32.is_ne(U32.and(visible,direction_bit(direction)),0)

law ungrouped_face_is_retained:
  for visible:U32
  {group_visible(None{},visible) == True{} : Bool}

def ungrouped_face_is_retained(visible):
  {==}

def retain_quad(visible:Bool,+quad:M_Quad,+reversed:List<&2,M_Quad>) -> List<&2,M_Quad>:
  match visible:
    case True{}: quad <> reversed
    case False{}: reversed

law retained_quad_is_exact:
  for +quad:M_Quad
  for +reversed:List<&2,M_Quad>
  {retain_quad(True{},quad,reversed) == quad <> reversed : List<&2,M_Quad>}

def retained_quad_is_exact(quad,reversed):
  {==}

def has_cell(values:List<&2,W_RawBlock>,+cell:W_Cell) -> Bool:
  match values:
    case Nil{}: False{}
    case W_RawBlock{other,state,material} <> tail: same_cell(cell,other) || has_cell(tail,cell)

def same_block(a:R_Block,b:R_Block) -> Bool:
  match a b:
    case R_Block{x,y,z,state,material} R_Block{bx,by,bz,bs,bm}:
      U32.is_eq(F32.bits(x),F32.bits(bx)) && U32.is_eq(F32.bits(y),F32.bits(by)) &&
        U32.is_eq(F32.bits(z),F32.bits(bz)) && U32.is_eq(state,bs) && U32.is_eq(material,bm)

def raw_material(raw:W_RawBlock,palette:W_Palette) -> Bool:
  W_RawBlock{cell,+state,+material} = raw
  W_Palette{air,stone,dirt,planks} = palette
  (U32.is_eq(state,stone) && U32.is_eq(material,0)) ||
    (U32.is_eq(state,dirt) && U32.is_eq(material,1)) ||
    (U32.is_eq(state,planks) && U32.is_eq(material,2))

def baked_flags(values:List<&2,K_Baked>,+visible:U32) -> List<&2,Bool>:
  match values:
    case Nil{}: []
    case K_Baked{a,b,c,d,direction,cf,sprite,texture,index,emission,override,layer,force,animated,ds,ns} <> tail:
      group_visible(cf,visible) <> baked_flags(tail,visible)

def binding_flags(binding:Maybe<&2,WM_Binding>,visible:U32) -> List<&2,Bool>:
  match binding:
    case None{}: []
    case Some{WM_Binding{state,baked,appearance}}: baked_flags(baked,visible)

def flags(values:List<&2,Visibility>,+bindings:List<&2,WM_Binding>) -> List<&2,Bool>:
  match values:
    case Nil{}: []
    case Visibility{cell,state,visible} <> tail:
      List.append(&2,Bool,binding_flags(WM_lookup(bindings,state),visible),flags(tail,bindings))

def filter_quads(values:List<&2,Bool>,quads:List<&2,M_Quad>,reversed:List<&2,M_Quad>) -> Result<&2,&2,Error,List<&2,M_Quad>>:
  match values quads:
    case Nil{} Nil{}: Done{List.reverse(&2,M_Quad,reversed)}
    case visible <> tail quad <> rest: filter_quads(tail,rest,retain_quad(visible,quad,reversed))
    case _ _: Fail{Error{"QuadAlignment",empty_cell(),0,"model-and-scene-count"}}
